public static String testableHtml(PageData pageData, boolean includeSuiteSetup) throws Exception {
    WikiPage wikiPage = pageData.getWikiPage();
    StringBuffer buffer = new StringBuffer();
    if (pageData.hasAttribute("Test")) {
        addSetupPages(buffer, wikiPage, includeSuiteSetup);
    }
    buffer.append(pageData.getContent());
    if (pageData.hasAttribute("Test")) {
        addTearDownPages(buffer, wikiPage, includeSuiteSetup);
    }
    pageData.setContent(buffer.toString());
    return pageData.getHTML();
}

private static void addSetupPages(StringBuffer buffer, WikiPage wikiPage, boolean includeSuiteSetup) throws Exception {
    if (includeSuiteSetup) {
        appendInheritedPage(buffer, wikiPage, SuiteResponder.SUITE_SETUP_NAME, "-setup");
    }
    appendInheritedPage(buffer, wikiPage, "SetUp", "-setup");
}

private static void addTearDownPages(StringBuffer buffer, WikiPage wikiPage, boolean includeSuiteSetup) throws Exception {
    appendInheritedPage(buffer, wikiPage, "TearDown", "-teardown");
    if (includeSuiteSetup) {
        appendInheritedPage(buffer, wikiPage, SuiteResponder.SUITE_TEARDOWN_NAME, "-teardown");
    }
}

private static void appendInheritedPage(StringBuffer buffer, WikiPage wikiPage, String pageName, String type) throws Exception {
    WikiPage page = PageCrawlerImpl.getInheritedPage(pageName, wikiPage);
    if (page != null) {
        WikiPagePath pagePath = page.getPageCrawler().getFullPath(page);
        String pagePathName = PathParser.render(pagePath);
        buffer.append("! include ").append(type).append(" .").append(pagePathName).append("\n");
    }
}
